import{_ as n,l as s,o as e,c as i,v as r,p as l,x as o,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"第 11 章破产","description":"","frontmatter":{"title":"第 11 章破产","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/chapter-11.md","filePath":"econ/chapter-11.md","lastUpdated":1789023840000}'),c={name:"econ/chapter-11.md"};function A(h,a,B,P,_,u){const t=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="第-11-章破产" tabindex="-1">第 11 章破产 <a class="header-anchor" href="#第-11-章破产" aria-label="Permalink to &quot;第 11 章破产&quot;">​</a></h1><div class="epigraph"><p>美国破产法第 11 章用自动中止和新融资优先权，把经营从债权人的个别催收里抢救出来；代价是偏离绝对优先、拖延，以及股权在钱里时的选择权。</p><footer>—— 据 Baird, The Elements of Bankruptcy；Franks and Torous, Journal of Finance 1989；Weiss, Journal of Financial Economics 1990</footer></div><p><a href="/econ/financial-distress-restructuring">上一课</a>把私下重组与法庭对照。本课缺口是第 11 章作为制度：自动中止、DIP 融资、计划表决、绝对优先规则（APR）的偏离。不重写 Andrade–Kaplan 的成本分解，不把各国破产法做成比较表——只取这套规则如何移动 Leland 的边界。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无法庭时，个别催收导致公共池：先到先得，资产被拆。第 11 章自动中止冻结催收，迫使集体谈判。DIP（debtor-in-possession）融资给予新钱超级优先，缓解积压（新投资不再只为旧债打工）。缺口是权衡：中止与 DIP 提高继续经营价值，也给现任经理与股权拖延的期权——Franks–Torous、Weiss 记录 APR 偏离（低级要求权得到不该得的）。事前，债权人要更高利息或更紧条款。</p><p><span class="marginnote">第 7 章是清算；第 11 章是重整。绝对优先：高优先级未全额前，低优先级为零。偏离来自表决规则、经理控制时间、以及需要股权配合确认计划。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对资本结构的含义：有效 \\(\\alpha\\) 下降（减少无序清算），但拖延增加间接成本，APR 偏离把价值漏向股权与经理。最优杠杆取决于哪一块大。对期限：中止切断加速到期的个别执行，短债的催收威胁减弱，条款的法庭外硬度更重要。</p><p>对资本预算：进入第 11 章的期权对股东是价值（看跌的公共保险），对债权人是成本。项目若提高进入概率，APV 要用债的损失而不是股权的期权价值去站队——为谁估值要声明。</p>',9)),(e(),l(E,null,{default:o(()=>[d(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20POOL%5B%22%E5%85%AC%E5%85%B1%E6%B1%A0%E5%82%AC%E6%94%B6%22%5D%20--%3E%20STAY%5B%22%E8%87%AA%E5%8A%A8%E4%B8%AD%E6%AD%A2%22%5D%0A%20%20STAY%20--%3E%20DIP%5B%22DIP%20%E6%96%B0%E9%92%B1%E4%BC%98%E5%85%88%22%5D%0A%20%20DIP%20--%3E%20OVER%5B%22%E5%87%8F%E8%BD%BB%E7%A7%AF%E5%8E%8B%22%5D%0A%20%20PLAN%5B%22%E8%AE%A1%E5%88%92%E4%B8%8E%E8%A1%A8%E5%86%B3%22%5D%20--%3E%20APR%5B%22APR%20%E5%8F%AF%E8%83%BD%E5%81%8F%E7%A6%BB%22%5D%0A%20%20DELAY%5B%22%E7%BB%8F%E7%90%86%E6%8B%96%E5%BB%B6%22%5D%20--%3E%20IND%5B%22%E9%97%B4%E6%8E%A5%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>Tirole：破产法是不完全合同的残差控制权配置。第 11 章把相当控制留给债务人，是亲继续经营、亲现任的配置；亲债权人的规则把 \\(V_B\\) 提高、杠杆降低。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是集体行动的法律技术。自动中止把分散债权人变成必须表决的集体；DIP 是法庭强制的优先新钱，纠正 Myers 积压。偏离 APR 是因为表决要拉票、以及法官对「可行性」的裁量——股权的期权在重整里继续活着。这与 Merton/Leland 的「边界上股权为零」不同：法律让边界模糊、股权仍有正价值。</p><p>与关系银行：银行常是 DIP 提供者或先偿，法庭内监督替代法庭外关系。公开债分散，靠委员会。证券化隔离实体若被并入实质合并，OTD 的真实出售失败。</p><h3 id="不是「破产就等于失败」" tabindex="-1">不是「破产就等于失败」 <a class="header-anchor" href="#不是「破产就等于失败」" aria-label="Permalink to &quot;不是「破产就等于失败」&quot;">​</a></h3><p>第 11 章可以是合同的执行阶段。事前杠杆与条款已经把进入概率定价。把进入本身当治理失败，会忽略故意靠近纪律边界的 LBO——后课私募股权。</p><p><span class="marginnote">Weiss（1990）测量直接成本与优先偏离。Franks–Torous 记录偏离的频率。机制课取方向：美国重整偏向继续经营与谈判，而不是瞬时 APR 清算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成程序时间表。下一课：即使有第 11 章，CDS 与分散持有仍使协调失败；空壳债权人可能投票反对有效重整。那是本单元收束。</p><p>后课默认：第 11 章降低无序清算、用 DIP 减积压，并以 APR 偏离与拖延为代价。Leland 的瞬时违约是近似；法律让股权在边界上仍有谈判价值。</p><p>本栏不讨论交易员如何买破产债权的微观结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自动中止解决公共池；DIP 给新钱优先以减轻积压。</li><li>APR 偏离与拖延是亲债务人重整的代价，事前进入债务价格。</li><li>破产法配置残差控制权，移动最优杠杆与 \\(V_B\\)。</li><li>出处：Franks and Torous, <em>JF</em> 1989；Weiss, <em>JFE</em> 1990；Baird。</li></ul>',13))])}const f=n(c,[["render",A]]);export{D as __pageData,f as default};
